topo-sort:
from collections import deque
indeg = {v: 0 for v in V}
for u, v in E: indeg[v] += 1
q = deque(v for v in V if indeg[v] == 0)
order = []
while q:
    u = q.popleft(); order.append(u)
    for v in adj[u]:
        indeg[v] -= 1
        if indeg[v] == 0: q.append(v)
return order if len(order) == |V| else 'cycle'

