tarjan-bridges:
disc = [-1]*n; low = [-1]*n; t = [0]; bridges = []
def dfs(u, parent):
    disc[u] = low[u] = t[0]; t[0] += 1
    for v in adj[u]:
        if disc[v] == -1:
            dfs(v, u)
            low[u] = min(low[u], low[v])
            if low[v] > disc[u]: bridges.append((u, v))
        elif v != parent:
            low[u] = min(low[u], disc[v])

euler-tour:
def hierholzer(start):
    stack = [start]; path = []
    while stack:
        u = stack[-1]
        if adj[u]:
            stack.append(adj[u].pop(0 if lex else -1))
        else:
            path.append(stack.pop())
    return path[::-1]

