# House Robber III — post-order returning (rob, skip)
def f(node):
    if not node: return (0, 0)
    lr, ls = f(node.left)
    rr, rs = f(node.right)
    return (node.val + ls + rs, max(lr, ls) + max(rr, rs))
return max(f(root))
